window.TEXTP = window.TEXTP || {};
window.TEXTP["49.4"] = [[["p","О обладатели разума! Разве непонятно, что если бы Всемогущий и Великий Аллах был везде и вместе с каждым человеком и каждым творением (как это утверждают му′аттылиты), то Он бы был виден каждой вещи и всему, что на земле?! А если бы Он был виден каждой вещи на земле — и равнинам, и ухабистым местам, и горам, и пустыням, и городам, и селениям, и населенным пунктам, и заброшенным местам, и всем растениям, и строениям, то Он превратил бы их в песок так же, как Он превратил в песок гору, показав Себя ей. Всевышний Аллах сказал: <b>«Когда же Господь его показался горе, то разбил ее и превратил в песок»</b><sup class=\"fn\">390</sup>."],["n",[[390,"Сура «аль-А′раф», аят 143."]]],["p","220 ― Сабит передал, что Анас ибн Малик (да будет доволен им Аллах) рассказывал, что, разъясняя слова Аллаха: <b>«Когда же Господь его показался горе, то разбил ее и превратил в песок», </b>(пророк, да благословит его Аллах и приветствует), сделал пальцем вот так, ― и он [передатчик хадиса Сабит] прикоснулся большим пальцем к ногтю мизинца<sup class=\"fn\">391</sup>."],["n",[[391,"То есть Аллах открыл Себя горе на размер ногтя мизинца."]]],["p","Услышав это, Хумейд сказал Сабиту: <i>«О Абу Мухаммад! Оставь это! Что ты хочешь этим сказать?!». </i>Тогда Сабит толкнул Хумейда в плечо и сказал: <i>«Кто ты такой, о Хумейд?! Кто ты такой, о Хумейд?! Это рассказал мне Анас ибн Малик от посланника Аллаха (да благословит его Аллах и приветствует), а ты говоришь: \"Оставь это\"?!»</i><sup class=\"fn\">392</sup><i>. </i>"],["n",[[392,"Ат-Тирмизи, 3074; Ахмад, 3/125; ′Абдуллах ибн Ахмад в «ас-Сунна», 542, 543; Ибн Аби ′Асым в «ас-Сунна», 481; Ибн Джарир в «Тафсире», 6/50; аль-Хаким, 3249; Ибн Манда в «ар-Радд ′аляль джахмия», 70, 71; ад-Дыя аль-Макдиси в «аль-Мухтара», 1674."]]],["p","Так передал этот хадис Яхья ибн Хаким."],["p","221 ― В другой версии пришло, что Сабит аль-Бунани передал со слов Анаса (да будет доволен им Аллах), что, разъясняя слова Аллаха: <b>«Когда же Господь его показался горе, то разбил ее и превратил в песок», </b>посланник Аллаха (да благословит его Аллах и приветствует) сделал вот так, ― и (передатчик этого хадиса) Му′аз разъяснил, что он (пророк) показал фалангу своего мизинцу."],["p","Услышав это, Хумейд ат-Тауиль сказал ему [Сабиту аль-Бунани]: <i>«О Абу Мухаммад! Что ты хочешь этим сказать?!». </i>(Сабит) сильно ударил его в грудь и сказал: <i>«Кто ты такой, о Хумейд?! Это рассказал мне Анас ибн Малик от посланника Аллаха (да благословит его Аллах и приветствует), а ты говоришь: \"Что ты хочешь этим сказать?\"?!». </i>"],["p","А один из передатчиков передал так: <i>«(Пророк, да благословит его Аллах и приветствует) приложил большой палец левой руки к кончику мизинца левой руки». </i>"],["p","222 ― В третьей версии пришло, что Сабит рассказывал со слов Анаса ибн Малика (да будет доволен им Аллах), что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Господь показался горе…» </i></b>― и тут он поднял свой мизинец и показал на его фалангу ― <b><i>«…и она разрушилась». </i></b>"]],[["p","Услышав это, Хумейд сказал ему [Сабиту аль-Бунани]: <i>«И ты рассказываешь такое?!». </i>Он ответил: <i>«Это рассказывал нам Анас от пророка (да благословит его Аллах и приветствует), а ты говоришь: \"Не рассказывай это!\"?!». </i>"],["p","223 ― В четвертой версии пришло, что Сабит передал со слов Анаса (да будет доволен им Аллах), что разъясняя слова Аллаха: <b>«Когда же Господь его показался горе, то разбил ее и превратил в песок», </b>пророк, да благословит его Аллах и приветствует, сказал: <b><i>«Показался (настолько)…», </i></b>и показал рукой вот так. (Тут передатчик этого хадиса) ′Аффан (ибн Муслим) показал на кончик своего мизинца, <b><i>«…и гора разрушилась». </i></b>"],["p","Услышав это, Хумейд сказал ему Сабиту: <i>«Неужели ты рассказываешь подобные вещи?!». </i>Тогда Сабит поднял руку, ударил его в грудь и сказал: <i>«Это рассказал мне Анас от посланника Аллаха (да благословит его Аллах и приветствует), а ты говоришь: \"Неужели ты рассказываешь подобные вещи?\"?!».</i>"],["p","224 ― Также этот хадис рассказал нам Мухаммад, которому рассказал аль-Хейсам ибн Джамиль, а ему рассказал Хаммад от Сабита, а тот — от Анаса (да будет доволен им Аллах)."],["p","225 ― В пятой версии пришло, что Сабит передал со слов Анаса (да будет доволен им Аллах), что пророк (да благословит его Аллах и приветствует) прочитал этот аят: <b>«Когда же Господь его показался горе, то разбил ее и превратил в песок, а Муса упал без сознания»,</b> положил свой мизинец на большой палец и сказал: <b><i>«И гора разрушилась и развалилась!». </i></b>"],["p","226 ― Также этот хадис рассказал нам Мухаммад, которому рассказал Хаджжадж ибн Минхаль от Хаммада ибн Салямы, а тот — от Сабита, который передавал его от Анаса (да будет доволен им Аллах)."],["p","227 ― Также этот хадис рассказал нам Мухаммад, которому рассказал Сулейман ибн Харб от Хаммада ибн Салямы, а тот — от Сабита, который передавал его от Анаса (да будет доволен им Аллах)."],["p","О обладатели разума! Послушайте же последний довод из Книги Аллаха, указывающий на то, что Великий и Возвышенный Аллах над небесами. Фараон был неверующим тираном, но Муса, мир ему, сообщил ему об этом. И Фараон как будто бы признавал, что Творец людей над небесами. Разве ты не слышал слова Аллаха, Который передал слова Фараона: <b>«О Хаман! Построй для меня башню. Быть может, я достигну путей, путей небесных, и взгляну на Бога Мусы»</b><sup class=\"fn\">393</sup>?!"],["n",[[393,"Сура «Гафир», аяты 36-37."]]],["p","Фараон (да пребудет над ним проклятие Аллаха) повелел возвести башню, считая, что сможет увидеть Бога Мусы. И он сказал: <b>«Воистину, я считаю его</b> [Мусу]<b> лжецом»</b><sup class=\"fn\">394</sup><b>. </b>Это указывает на то, что Муса сообщил ему о том, что его Великий и Возвышенный Господь находится вверху. Я считаю, что Фараон сказал своему народу: <b>«Воистину, я считаю его лжецом», </b>чтобы завлечь их в неверие. Великий и Возвышенный Аллах сообщил нам: <b>«И они отвергли их </b>[девять чудес Мусы<b>], хотя сами они были убеждены в их (истинности), по неправедности и высокомерию»</b><sup class=\"fn\">395</sup>. Всевышний Аллах сообщил, что эта группа отвергла своими языками (истину), хотя их сердца были убеждены в ней. И когда Фараон сказал своему народу: <b>«Воистину, я считаю его лжецом», </b>вероятно, его сердце было убеждено в том, что Муса был из числа правдивых, а не лжецов. А Аллах знает лучше!"],["n",[[394,"Сура «Гафир», аят 37."],[395,"Сура «ан-Намль», аят 14."]]]],[["p","И любимец Аллаха Ибрахим (мир ему) с самого начала, когда посмотрел на звезду, луну и солнце, знал, что его Творец возвышен над Своими творениями. Разве ты не слышал его слова: <b>«Это — Господь мой?»</b><sup class=\"fn\">396</sup>. Он не искал своего Творца внизу. Он искал Его вверху, так как был убежден в том, что его Господь над небесами, а не на земле."],["n",[[396,"Сура «аль-Ан′ам», аят 76."]]],["p","ГЛАВА 29: УПОМИНАНИЕ СУННЫ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), КОТОРАЯ РАЗЪЯСНЯЕТ, ЧТО АЛЛАХ НАД ВСЕМ СУЩИМ, И ЧТО ОН — НАД НЕБЕСАМИ, КАК ОН СООБЩИЛ НАМ ОБ ЭТОМ В СВОЕМ ОТКРОВЕНИИ, ЧЕРЕЗ УСТА СВОЕГО ПРОРОКА. ВЕДЬ ЕСЛИ ЕГО СУННА ПЕРЕДАНА ОТ НЕГО ЧЕРЕЗ ПРАВДИВЫХ ПЕРЕДАТЧИКОВ, ТО ОНА ОБЯЗАТЕЛЬНО БУДЕТ СООТВЕТСТВОВАТЬ КНИГЕ АЛЛАХА И НЕ БУДЕТ ЕЙ ПРОТИВОРЕЧИТЬ"],["p","228 ― Абу Хурейра (да будет доволен им Аллах) рассказывал: <i>«Однажды Фатыма пришла к посланнику Аллаха (да благословит его Аллах и приветствует) и попросила его предоставить ей слугу, а он ответил: </i><b><i>«Говори: \"О Аллах! Господь семи небес, Господь великого трона, наш Господь и Господь всякой вещи, Который ниспослал Тору и Евангелие\"».</i></b>"],["p","<i>А однажды он сказал: </i><b><i>\"…и (ниспослал) великий Коран, и Тот, Кто расщепляет зёрна и ядра! Я прибегаю к Твоей защите от зла всего дурного, ибо всё это подвластно Тебе! Ты — Первый, и не было ничего до Тебя, Ты − Последний, и не будет ничего после Тебя, Ты − Явный, и нет ничего над Тобой, и Ты — Скрытый, и нет ничего ближе Тебя! Избавь же нас от долга и избавь нас от бедности!\"</i></b><i>»</i><sup class=\"fn\">397</sup>."],["n",[[397,"Муслим, 2713; ат-Тирмизи, 3481; Ибн Хиббан, 966."]]],["p","229 ― Также этот хадис рассказал нам Мухаммад ибн уль-Хараший, которому рассказал Зияд ибн ′Абдуллах аль-Бикаи, а ему рассказал аль-А′маш."],["p","230 ― Абу Хурейра (да будет доволен им Аллах) также рассказывал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) велел нам говорить, когда один из нас ложится на своё ложе: </i><b><i>\"О Аллах! Господь небес, Господь земли, наш Господь и Господь всякой вещи, Тот, Кто расщепляет зёрна и ядра, и Тот, Кто ниспослал Тору, Евангелие и Коран! Я прибегаю к Твоей защите от зла всего дурного, ибо всё это подвластно Тебе! Ты — Первый, и не было ничего до Тебя, Ты − Последний, и не будет ничего после Тебя, Ты − Явный, и нет ничего над Тобой, и Ты — Скрытый, и нет ничего ближе Тебя! Избавь же меня от долга и избавь меня от бедности!\"</i></b><i>»</i><sup class=\"fn\">398</sup>."],["n",[[398,"Муслим, 2713; Абу Дауд, 5051."]]],["p","231 ― Абу Хурейра (да будет доволен им Аллах) также рассказывал: <i>«Когда посланник Аллаха (да благословит его Аллах и приветствует) ложился на своё ложе, он говорил: </i><b><i>\"О Аллах! Господь небес, Господь земли и Господь всякой вещи, Тот, Кто расщепляет зёрна и ядра, и Тот, Кто ниспослал Тору и Евангелие! Защити меня от зла всего дурного, ибо всё это подвластно Тебе! Ты — Первый, и не было ничего до Тебя, Ты — Скрытый, и нет ничего ближе Тебя, Ты − Явный, и нет ничего над Тобой! Избавь же меня от долга и избавь меня от бедности!\"</i></b><i>».</i>"]],[["p","232 ― Также похожий хадис рассказал нам Абу Яхья Мухаммад ибн ′Абд ур-Рахим, которому рассказал ′Аффан ибн Муслим, а ему рассказал Вухейб."],["p","233 ― Абу Хурейра (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Ангелы, которые пребывают среди вас ночью, и ангелы, которые пребывают среди вас днём, (постоянно) сменяют друг друга, встречаясь друг с другом во время утренней (фаджр) и послеобеденной (′аср) молитв. После этого те (ангелы), которые провели среди вас ночь, возносятся (к небесам), и Аллах, знающий о (положении людей) лучше (ангелов), спрашивает их: \"В каком (положении) оставили вы рабов Моих?\", — а они отвечают: \"Мы покинули их, когда они молились, и когда мы пришли к ним, они (тоже) молились\"»</i></b><sup class=\"fn\">399</sup>."],["n",[[399,"Аль-Бухари, 555, 3223; Муслим, 632; Ахмад, 2/312."]]],["p","234 ― Абу Хурейра (да будет доволен им Аллах) также передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у Всемогущего и Великого Аллаха есть ангелы, которые сменяют друг друга среди вас. Когда наступает время утренней молитвы (фаджр), нисходят ангелы дня, и все они присутствуют с вами на этой молитве, после чего ангелы ночи возносятся (на небеса), а ангелы дня остаются с вами. Их Господь спрашивает их, хотя Он более знающ, чем они: \"Что делали Мои рабы, когда вы оставили их?\". Они отвечают: \"Мы пришли к ним, и они совершали молитву, и когда мы уходили, они тоже совершали молитву!\".</i></b>"],["p","<b><i>А когда наступает время послеобеденной молитвы (′аср), нисходят ангелы ночи, и все они присутствуют с вами на этой молитве, после чего ангелы дня возносятся (на небеса), а ангелы ночи остаются с вами. Их Господь спрашивает их, хотя Он более знающ, чем они: \"Что делали Мои рабы, когда вы оставили их?\". Они отвечают: \"Мы пришли к ним, и они совершали молитву, и когда мы уходили, они тоже совершали молитву!\". И они также говорят: \"Прости им в День Воздаяния!\"»</i></b><sup class=\"fn\">400</sup>."],["n",[[400,"Ад-Дарими в «ар-Радд ′аля-ль джахмия», 92; Ибн Хиббан в «Сахихе», 2061."]]],["p","235 ― Также подобный хадис рассказал нам Яхья ибн Хаким, которому рассказал Яхья ибн Хаммад, а ему рассказал Абу ′Ауана от Сулеймана аль-А′маша."],["p","236 ― Абу Са′ид аль-Худри (да будет доволен им Аллах) рассказывал о том, как пророк (да благословит его Аллах и приветствует) делил (между людьми) золото, которое отправил ′Али ибн Аби Талиб из Йемена. Пророк (да благословит его Аллах и приветствует) сказал (людям): <b><i>«Я — доверенный Того, Кто над небесами!»</i></b><sup class=\"fn\">401</sup>."],["n",[[401,"Аль-Бухари, 4351; Муслим, 1064; Ахмад, 3/4."]]],["p","237 ― Также в других своих книгах я привёл хадисы о вознесении пророка (да благословит его Аллах и приветствует) на небеса (аль-ми′радж). В этих хадисах говорится о том, что к пророку (да благословит его Аллах и приветствует) привели (животное, именуемое) Бурак, и он рассказывал: <b><i>«Меня посадили на него, и я двинулся в путь, пока мы не пришли к ближнему небу»</i></b>. Это — часть длинного хадиса<sup class=\"fn\">402</sup>."],["n",[[402,"Аль-Бухари, 3887; Муслим, 164."]]]],[["p","В этих хадисах ясное указание на то, что пророк (да благословит его Аллах и приветствует) был вознесён с земли на седьмое небо, и Всевышний Аллах вменил ему в обязанность молитвы. Все эти хадисы указывают на то, что Создатель и Творец находится над семью небесами, а не так, как утверждают му′аттылиты, что их Бог с ними в их домах и в их уборных<sup class=\"fn\">403</sup>."],["n",[[403,"Так как джахмиты и их последователи утверждали, что Аллах находится везде."]]],["p","238 ― Аль-Бара (да будет доволен им Аллах) привёл хадис о том, как ангелы забирают душу верующего и душу неверующего. Пророк (да благословит его Аллах и приветствует) сказал о том, как они забирают душу верующего: <b><i>«И (этот ангел) говорит: \"О благая и умиротворенная душа! Выходи к прощению Аллаха и Его довольству!\". Тогда (эта душа) покидает (тело) так легко, как вытекает капля из бурдюка. И когда (ангелы) берут ее, то не оставляют ее в своих руках даже на мгновение ока, а возносят её на небеса, и мимо какого бы воинства из числа ангелов они не проходили с ней, те обязательно спрашивают: ″Что это за благая душа?!″, а (ангелы, несущие душу), отвечают: ″(Это душа) такого-то!\", перечисляя наилучшие его имена. А когда они доходят с ней до небес, пред ней раскрываются небесные врата, и на каждом небе эту (душу) провожают приближенные (ангелы) этого неба, (следуя за ней) до следующего неба, и так они достигают седьмого неба, а затем говорится: \"Запишите Его книгу в ′Иллиййюне!\"».</i></b> Это — часть длинного хадиса<sup class=\"fn\">404</sup>."],["n",[[404,"Абу Дауд, 4753; Ахмад, 4/287; ′Абдуллах в «ас-Сунна», 1543; Ибн Манда в «аль-Иман», 1064; Ханнад в «аз-Зухд», 339; Ибн Аби Шейба в «Мусаннафе», 12059."]]],["p","239 ― Также подобный хадис рассказал нам ′Али ибн уль-Мунзир, которому рассказал Ибн Фудейль, а ему рассказал аль-А′маш."],["p","240 ― Аль-Бара ибн ′Азиб (да будет доволен им Аллах) также передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«А когда его душа</i></b><sup class=\"fn\">405</sup><b><i> выходит, её благословляет каждый ангел между небесами и землей и каждый ангел на небесах, и раскрываются (пред ней) врата небес, и ангелы возле каждых врат просят Аллаха, чтобы эта душа была вознесена именно через них, а когда его душу возносят, они говорят: \"Господь! Это — Твой раб, такой-то!\". (Аллах) говорит: \"Верните его (на землю)! Поистине, Я обещал им, что из неё Я сотворил их, и в неё Я их верну, и из неё Я выведу их ещё раз!\"»</i></b><sup class=\"fn\">406</sup>."],["n",[[405,"То есть душа верующего."],[406,"Ахмад, 4/195; ′Абд ур-Раззак в «Мусаннафе», 6737; ′Абдуллах в «ас-Сунна», 547."]]],["p","241 ― Абу Хурейра (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«К умирающему приходят ангелы, и если человек был праведным, ему говорят: \"Выходи, о благая душа, пребывавшая в благом теле! Выходи, будучи восхваляемой (пред Аллахом), и радуйся милости и благоуханию, и Господу, Который не гневается!\", и они говорят это, пока она не выйдет. Когда же она выходит, её возносят на небеса и просят для неё разрешения войти (на первое небо). (Ангелы первого неба) говорят: \"Кто это?\", а (ангелы, несущие душу), отвечают: \"Такой-то!\". Тогда ей говорят: \"Добро пожаловать, о благая душа, пребывавшая в благом теле! Входи будучи восхваляемой и радуйся милости и благоуханию, и Господу, Который не гневается!\". И ей продолжают говорить это, пока не поднимают ее до тех небес, над которыми Всеблагой и Всевышний Господь»</i></b><sup class=\"fn\">407</sup>."],["n",[[407,"Ахмад, 2/364; Ибн Маджа, 4262; ан-Насаи в «ас-Сунан аль-кубра», 11442; ′Абдуллах ибн Ахмад в «ас-Сунна», 1554; Ибн Манда в «аль-Иман», 1068; аль-Аджурри в «аш-Шари′а», 979."]]]],[["p","242 ― ′Имран ибн Хусайн рассказывал: <i>«Однажды курейшиты пришли к аль-Хусайну, которого они возвеличивали, и сказали ему: \"Поговори ради нас с этим человеком, ибо он упоминает наших богов и ругает их!\". Затем они пришли вместе с ним и сели недалеко от дверей пророка (да благословит его Аллах и приветствует). Аль-Хусайн вошёл, и когда пророк (да благословит его Аллах и приветствует) увидел его, он сказал: </i><b><i>\"Сделайте место для шейха!\". </i></b><i>Аль-Хусайн сказал: \"Что это за слова доходит до нас от тебя?! (До нас дошло), что ты упоминаешь наших богов и ругаешь их, а ведь твой отец был благородным человеком!\". (Пророк, да благословит его Аллах и приветствует), ответил: </i><b><i>\"О Хусайн! Воистину, мой отец и твой отец в Огне! О Хусайн! Скольким богам ты поклоняешься сегодня?!\". </i></b><i>Он ответил: \"Семерым, которые на земле, и Одному, Который над небесами!\". (Пророк, да благословит его Аллах и приветствует), спросил: </i><b><i>\"А к какому ты взываешь, когда тебя постигает вред?!\". </i></b><i>Он ответил: \"К Тому, Который над небесами\". (Пророк, да благословит его Аллах и приветствует), спросил: </i><b><i>\"А к какому ты взываешь, когда гибнет твоё имущество?!\".</i></b> <i>Он ответил: \"К Тому, Который над небесами\". (Пророк, да благословит его Аллах и приветствует), сказал: </i><b><i>\"Тебе отвечает лишь Один, а ты всё равно придаешь их Ему в сотоварищи?!\"»</i></b><sup class=\"fn\">408</sup>."],["n",[[408,"Также передали ат-Тирмизи, 3483; ат-Табарани в «аль-Му′джам аль-кабир», 18/174; аль-Бейхакы в «аль-Асма уа ссыфат», 894; аль-Лялякаи в «И′тикад ахли ссунна», 1184."]]],["p","ГЛАВА 30: УПОМИНАНИЕ ДОВОДА, УКАЗЫВАЮЩЕГО НА ТО, ЧТО ПРИЗНАНИЕ ВОЗВЫШЕННОСТИ АЛЛАХА НАД НЕБЕСАМИ — ЭТО ЧАСТЬ ВЕРЫ (ИМАНА)"],["p","243 ― Му′ауия ибн уль-Хакам ас-Сулями (да будет доволен им Аллах) рассказывал: <i>«У меня были овцы, которых пасла моя рабыня перед Ухудом и аль-Джавванией. Однажды я узнал, что волк увёл у неё овцу. Я — такой же человек, как и все потомки Адама. Я могу огорчиться, также как и все остальные. Случилось так, что я дал ей пощёчину. А когда я отправился к посланнику Аллаха (да благословит его Аллах и приветствует), он счёл это серьезным проступком. Тогда я сказал: \"О посланник Аллаха! Может быть мне освободить её?!\". Он ответил: </i><b><i>\"Приведи её ко мне\". </i></b><i>Когда я привёл её к посланнику Аллаха (да благословит его Аллах и приветствует), он спросил её: </i><b><i>\"Где Аллах?\". </i></b><i>Она ответила: \"Над небесами\". Он спросил: </i><b><i>\"А кто я?\". </i></b><i>Она ответила: \"Ты — посланник Аллаха\". Тогда он сказал: </i><b><i>\"Она — верующая! Освободи её!\"</i></b><i>»</i><sup class=\"fn\">409</sup>."],["n",[[409,"Муслим, 537; Абу Дауд, 930, 3282; ан-Насаи, 3/14; Ахмад, 5/448; ат-Таялиси, 1105; Ибн Хиббан, 165, 2247; Ибн Аби Шейба в «Мусаннафе», 30342; Ибн Аби ′Асым в «ас-Сунна», 489 и др."]]]],[["p","244 ― Также этот хадис рассказали нам Бандар и Абу Кудама по другой цепочке передатчиков."],["p","245 ― Также этот хадис рассказал нам ар-Раби′ ибн Сулейман аль-Муради, которому сообщил аш-Шафи′и, а ему рассказал Малик."],["p","246 ― Абу Хурейра (да будет доволен им Аллах) рассказывал о том, что Мухаммад ибн уш-Шарид однажды пришёл к посланнику Аллаха (да благословит его Аллах и приветствует) с чернокожей рабыней и сказал: <i>«О посланник Аллаха! Моя мать дала обет освободить верующего раба. Могу ли я освободить эту (рабыню)?!». </i>Посланник Аллаха (да благословит его Аллах и приветствует) спросил у рабыни: <b><i>«Где Аллах?». </i></b>Она подняла голову вверх и сказала: <i>«Над небесами». </i>Он спросил: <b><i>«А кто я?». </i></b>Она ответила: <i>«Ты — посланник Аллаха». </i>Тогда он сказал: <b><i>«Освободи её, ведь, поистине, она — верующая!»</i></b><sup class=\"fn\">410</sup>."],["n",[[410,"Абу Дауд, 3283; ан-Насаи, 6/252; Ахмад, 4/222; Ибн Хиббан, 189; ат-Табарани в «аль-Му′джам аль-кабир», 7/320; аль-Бейхакы в «ас-Сунан аль-кубра», 7/388."]]],["p","247 ― Абу Хурейра (да будет доволен им Аллах) также рассказывал: <i>«Однажды некий человек пришёл к посланнику Аллаха (да благословит его Аллах и приветствует) с невольницей, которая не относилась к числу арабок. (Этот человек) сказал: \"О посланник Аллаха! Поистине, на мне лежит освобождение верующего раба. Могу ли я освободить эту (рабыню)?\". Посланник Аллаха (да благословит его Аллах и приветствует) спросил её: </i><b><i>\"Где Аллах?\", </i></b><i>а она указала на небеса. Посланник Аллаха (да благословит его Аллах и приветствует) спросил: </i><b><i>\"А кто я?\", </i></b><i>и она указала сначала на посланника Аллаха (да благословит его Аллах и приветствует), а затем — на небо, имея в виду: \"Ты — посланник Аллаха\". Тогда посланник Аллаха (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Освободи её, ведь, поистине, она — верующая!\"</i></b><i>»</i><sup class=\"fn\">411</sup><i>.</i>"],["n",[[411,"Ахмад, 2/291; Абу Дауд, 3284; аль-Бейхакы в «ас-Сунан аль-кубра», 7/388; аль-Лялякаи в «И′тикад ахли ссунна», 653."]]],["p","248 ― В другой версии сказано: <i>«…пришёл с чернокожей рабыней, которая не могла ясно выразить свои мысли. (Этот человек) сказал: \"На мне лежит освобождение верующего раба\". Посланник Аллаха (да благословит его Аллах и приветствует) сказал ей: </i><b><i>\"Кто твой Господь?\"</i></b><i>, а она (в ответ) указала рукой на небеса. Затем он спросил: </i><b><i>\"А кто я?\", </i></b><i>и тогда она указала рукой сначала на небеса, а затем — на землю, имея в виду: \"Посланник Аллаха\"», </i>и до конца хадиса."],["p","249 ― Также этот хадис рассказал нам Мухаммад ибн Ма′мар, которому рассказал Абу Дауд, а ему рассказал аль-Мас′уди, которому рассказал ′Аун ибн ′Абдуллах ибн ′Утба."],["p","250 ― А аз-Зухри передал, что ′Убейдуллах ибн ′Абдуллах ибн ′Утба рассказывал со слов одного из ансаров, что он пришёл (к посланнику Аллаха, да благословит его Аллах и приветствует), с чернокожей женщиной и сказал: <i>«О посланник Аллаха! На мне лежит освобождение верующего раба. Если ты считаешь её верующей, то могу ли я её освободить?!». </i>Пророк (да благословит его Аллах и приветствует) спросил: <b><i>«Ты свидетельствуешь, что нет истинного бога, кроме Аллаха?!». </i></b>Она ответила: <i>«Да». </i>Он спросил: <b><i>«А ты свидетельствуешь, что я — посланник Аллаха?!». </i></b>Она ответила: <i>«Да». </i>Он спросил: <b><i>«А ты веруешь в воскрешение после смерти?!». </i></b>Она ответила: <i>«Да». </i>Тогда он сказал: <b><i>«Освободи её!»</i></b><sup class=\"fn\">412</sup>."],["n",[[412,"′Абд ур-Раззак в «Мусаннафе», 9/175; Ахмад, 3/451; Ибн уль-Джаруд в «аль-Мунтака», 931. Также его передали Малик в «аль-Муватта», стр. 777; аль-Бейхакы в «ас-Сунан аль-кубра», 7/388."]]]],[["p","251 ― Также этот хадис передал Малик от Ибн Шихаба, а тот — от ′Убейдуллаха ибн ′Абдуллаха, который передавал сразу от пророка (да благословит его Аллах и приветствует) без упоминания сподвижника."],["p","252 ― Также подобный хадис рассказал нам Мухаммад ибн ′Абд уль-Уаххаб, которому рассказал аль-Хусейн ибн уль-Уалид ан-Нейсабури от Малика, а тот — от аз-Зухри, который передавал от ′Убейдуллаха, а тот — от Абу Хурейры (да будет доволен им Аллах)."],["p","Нет никаких сомнений в том, что это является ошибкой, так как Малик, передавая этот хадис, не упоминал Абу Хурейру. Что касается Ма′мара, то он в своей версии сказал: <i>«…от одного из ансаров…». </i>А Абу Хурейра не был ансаром. Он происходил из племени Даус. При этом я не отрицаю, что передача Ма′мара является установленной и достоверной. А ′Убейдуллах ибн ′Абдуллах мог передавать этот хадис и от Абу Хурейры, и от одного из ансаров, даже если речь шла бы об одном и том же хадисе. А что сказать о том, когда приведены два разных хадиса?! Я считаю, что это — два разных хадиса, а не один. В хадисе со слов ′Ауна ибн ′Абдуллаха пришло, что чернокожая рабыня ответила путем жестов и ничего не говорила языком. А в хадисе со слов аз-Зухри сказано, что чернокожая рабыня сказала: «Да» — после того, как посланник Аллаха (да благословит его Аллах и приветствует) сказал ей: <b><i>«Ты свидетельствуешь, что нет истинного бога, кроме Аллаха?!». </i></b>И также, когда он сказал ей: <b><i>«А ты свидетельствуешь, что я — посланник Аллаха?!», </i></b>она ответила: «Да», произнеся эти слова языком. Также в хадисе со слов аз-Зухри есть дополнительный вопрос о воскрешении после смерти. Поймите же это, и вы не обманетесь!"],["p","ГЛАВА 31: УПОМИНАНИЕ ДОСТОВЕРНЫХ ПРЕДАНИЙ, КОТОРЫЕ ПЕРЕДАЛИ УЧЕНЫЕ ХИДЖАЗА И ИРАКА ОТ ИЗБРАННОГО ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ), О ТОМ, ЧТО ВЕЛИКИЙ И ВОЗВЫШЕННЫЙ ГОСПОДЬ НИСХОДИТ К БЛИЖНЕМУ НЕБУ КАЖДУЮ НОЧЬ"],["p","Мы свидетельствуем, признавая языком, подтверждая сердцем и будучи убежденными в том, что приходит в этих сообщениях, в которых упоминается нисхождение Господа, которое мы не описываем образом, ведь наш пророк (да благословит его Аллах и приветствует) не описал нам образ нисхождения нашего Творца на ближнее небо, но при этом он сообщил нам, что Аллах нисходит. Великий и Возвышенный Аллах и Его пророк (да благословит его Аллах и приветствует) разъяснили всё, в чём мусульмане нуждаются из дел своей религии. И мы говорим и подтверждаем правдивость того, что в этих преданиях, в которых упоминается нисхождение, но мы не обременяем себя словами об образе этого нисхождения, ведь пророк (да благословит его Аллах и приветствует) не описал нам образ нисхождения."]],[["p","В этих преданиях достоверно пришло, что Великий и Возвышенный Аллах находится над ближним небом, и пророк (да благословит его Аллах и приветствует) сообщил нам, что Он нисходит к этому небу<sup class=\"fn\">413</sup>. Ведь в арабском языке невозможно сказать, что кто-то нисходит снизу вверх. Из арабского языка понимается, что нисхождение (нузуль) происходит сверху вниз."],["n",[[413,"Пусть уважаемый читатель обратит внимание, как много хадисов по различным путям передачи и от разных сподвижников переданы на эту тему, и поэтому тем более удивительно, как люди могут отрицать этот атрибут Всевышнего Аллаха."]]],["p","253-254 ― аль-Агарр рассказывал: «Я свидетельствую, что Абу Хурейра и Абу Са′ид аль-Худри (да будет доволен ими Аллах) свидетельствовали, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Аллах ждёт, пока пройдет треть ночь, а затем нисходит и говорит: \"Кто просит?! Кто кается?! Кто просит прощения в грехах?!\"». </i></b>Тогда некий человек спросил: <i>«И так, пока не появится заря?!». </i>Пророк (да благословит его Аллах и приветствует) ответил: <b><i>«Да»</i></b><sup class=\"fn\">414</sup>."],["n",[[414,"Муслим, 758; Ахмад, 3/34; ат-Табарани в «ад-Ду′а», 142; аль-Лялякаи в «И′тикад ахли ссунна», 746 и др."]]],["p","255 ― В другой версии пришло: <b><i>«Поистине, Аллах ждёт, а когда проходит треть ночи, Он нисходит на ближнее небо и говорит: \"Есть ли просящий прощения?! Есть ли взывающий?! Есть ли просящий (о чем-нибудь)?!\". И так, пока не появляется заря»</i></b><sup class=\"fn\">415</sup>."],["n",[[415,"Ахмад, 2/383; ат-Табарани в «ад-Ду′а», 143."]]],["p","256 ― Также похожий хадис рассказал нам Юсуф ибн Муса, которому рассказал Джарир от Мансура, а тот — от Абу Исхака<sup class=\"fn\">416</sup>."],["n",[[416,"Муслим, 758; Ибн Хиббан, 921; Ибн Аби Шейба, 29556; ат-Табарани в «ад-Ду′а», 144; аль-Лялякаи в «И′тикад ахли ссунна», 747; ан-Насаи в «ас-Сунан аль-кубра», 10315."]]],["p","257 ― Также похожий хадис рассказал нам Ахмад ибн Са′ид ар-Рибаты, которому рассказал Мухадыр ибн уль-Муварри′ Абу-ль Муварри′, которому рассказал аль-А′маш от Абу Салиха, который сказал: «Передается от Абу Са′ида или от Абу Хурейры»."],["p","258 ― Абу Хурейра (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Аллах ждёт, пока пройдёт первая половина ночи, а затем нисходит на ближнее небо и говорит: \"Есть ли просящий о прощении, чтобы Я простил его?! Есть ли просящий, чтобы Я даровал ему?! Есть ли кающийся, чтобы Я принял его покаяние?!\". И так, пока не появится заря»</i></b><sup class=\"fn\">417</sup>."],["n",[[417,"Ибн Аби ′Асым в «ас-Сунна», 501, 502; аль-Лялякаи, 752; ан-Насаи в «ас-Сунан аль-кубра», 10316; ат-Табарани в «ад-Ду′а», 146."]]],["p","259 ― Также похожий хадис рассказал нам Ахмад ибн Са′ид, а ему рассказал Мухадыр от аль-А′маша, а тот — от Абу Суфьяна, а он — от Джабира, в версии которого пришло: <b><i>«…и так происходит каждую ночь…». </i></b>"]],[["p","260 ― Также похожий хадис рассказал нам Исхак ибн Уахб аль-Уаситы, которому рассказал Мухадыр ибн уль-Муварри′, а ему рассказал аль-А′маш от Абу Салиха, который передавал от Абу Са′ида и Абу Хурейры."],["p","261 ― Абу Хурейра (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Аллах ждёт, пока пройдёт первая половина ночи, а затем нисходит на ближнее небо и говорит: \"Есть ли просящий о прощении, чтобы Я простил его?! Есть ли просящий, чтобы Я даровал ему?! Есть ли кающийся, чтобы Я принял его покаяние?!\". И так, пока не появится заря»</i></b>."],["p","262 ― А в другой версии со слов Джабира ибн ′Абдуллаха (да будет доволен Аллах им и его отцом) сказано: <b><i>«…и так происходит каждую ночь…». </i></b>"],["p","263 ― В другой версии со слов Абу Хурейры (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Всеблагой и Всевышний Аллах каждую ночь нисходит к ближнему небу, когда наступает последняя треть ночи, и говорит: \"Кто взывает ко Мне, чтобы Я ответил ему?! Кто просит Меня, чтобы Я даровал ему?! Кто просит о прощении Меня, чтобы Я простил ему?!\"»</i></b><sup class=\"fn\">418</sup>."],["n",[[418,"Аль-Бухари, 1145, 6321, 7494; Муслим, 758; ′Абдуллах ибн Ахмад в «ас-Сунна», 1189; Ибн Аби ′Асым в «ас-Сунна», 492; ад-Дарими в «ар-Радд ′аляль джахмия», 125."]]],["p","264 ― В другой версии сказано: <b><i>«Нисходит наш Господь…». </i></b>"],["p","265 ― Также похожий хадис рассказал нам Ахмад от своего дяди, которому рассказал Юнус от аз-Зухри, а тот — от Абу Салямы ибн ′Абд ур-Рахмана и Абу ′Абдуллаха аль-Агарра, которые слышали от Абу Хурейры (да будет доволен им Аллах)."],["p","266 ― Также этот хадис рассказал нам Яхья ибн Хаким, которому рассказал Абу Дауд, а ему рассказал Ибрахим ибн Са′д от аз-Зухри, который передавал от Абу Салямы и аль-Агарра, которые передавали от Абу Хурейры (да будет доволен им Аллах), который передал эти слова от посланника Аллаха (да благословит его Аллах и приветствует)<sup class=\"fn\">419</sup>."],["n",[[419,"Ан-Насаи в «ас-Сунан аль-кубра», 10313, 10314; Ибн Маджа, 1366; ′Абдуллах ибн Ахмад в «ас-Сунна», 1288; Ибн Аби ′Асым в «ас-Сунна», 493."]]],["p","267 ― Также этот хадис рассказал нам Мухаммад ибн Яхья, которому рассказал Я′куб ибн Ибрахим, а ему рассказал его отец от Ибн Шихаба, а тот — от Абу ′Абдуллаха аль-Агарра, который передавал от Абу Хурейры (да будет доволен им Аллах)."],["p","268 ― Также этот хадис рассказал нам Мухаммад, которому рассказал ′Абд ур-Раззак, а ему рассказал Ма′мар от аз-Зухри."],["p","269 ― Также этот хадис рассказал нам Мухаммад, которому рассказал Абу-ль Яман, а ему рассказал Шу′айб от аз-Зухри."]],[["p","270 ― В другой версии со слов Абу Хурейры (да будет доволен им Аллах) пришло, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Когда проходит первая половина ночи (или: две трети ночи) Всеблагой и Всевышний Аллах нисходит на ближнее небо и говорит: \"Есть ли просящий, и ему будет даровано?! Есть ли взывающий, и ему будет отвечено?! Есть ли просящий о прощении, и ему будет прощено?!\", и так до самого утра»</i></b><sup class=\"fn\">420</sup>."],["n",[[420,"Муслим, 758; ан-Насаи в «ас-Сунан аль-кубра», 10312; Ибн Аби ′Асым в «ас-Сунна», 497."]]],["p","271 ― В другой версии со слов Абу Хурейры (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Великий и Возвышенный Аллах нисходит каждую ночь на ближнее небо во вторую половину ночи (или: в последнюю треть ночи) и говорит: \"Кто взывает ко Мне, чтобы Я ответил ему?! Кто просит Меня, чтобы Я даровал ему?! Кто просит Меня о прощении, чтобы Я простил его?!\", и так до самого утра (или: пока чтец не завершит утреннюю молитву)»</i></b><sup class=\"fn\">421</sup>."],["n",[[421,"Ахмад, 2/504; ′Абдуллах ибн Ахмад в «ас-Сунна», 1289, 1291; Ибн Аби ′Асым в «ас-Сунна», 495, 496; Ханнад в «аз-Зухд», 884."]]],["p","272 ― Также похожий хадис рассказал нам Мухаммад ибн Башшар, которому рассказал ′Абд уль-Уаххаб, а ему рассказал Мухаммад ибн ′Амр."],["p","273 ― Также похожий хадис рассказал нам Мухаммад ибн Башшар, которому рассказал ′Абд уль-А′ля, а ему рассказал Мухаммад ибн ′Амр."],["p","274 ― Также похожий хадис рассказал нам Зейд ибн Ахзам, которому рассказал Уахб ибн Джарир, а ему рассказал его отец, который слышал, как ан-Ну′ман ибн Рашид рассказывал от аз-Зухри, а тот — от Абу Салямы, а он — от Абу Хурейры (да будет доволен им Аллах)."],["p","275 ― В другой версии со слов Абу Хурейры (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Наш Всеблагой и Всевышний Господь нисходит каждую ночь, когда проходит её первая треть, и говорит: \"Я — Царь! Я — Царь! Кто просит Меня, чтобы Я даровал ему?! Кто взывает ко Мне, чтобы Я ответил ему?! Кто просит Меня о прощении, чтобы Я простил ему?!\", и так продолжается до появления зари»</i></b><sup class=\"fn\">422</sup>."],["n",[[422,"Муслим, 758; ат-Тирмизи, 446; Ахмад, 2/282, 419."]]],["p","276 ― Также похожий хадис рассказал нам Мухаммад ибн ′Абд уль-А′ля ас-Сан′ани, которому рассказал аль-Му′тамир, который слышал, как ′Убейдуллах передавал от Са′ида ибн Аби Са′ида, который передавал со слов своего отца, а тот — от Абу Хурейры (да будет доволен им Аллах)."],["p","277 ― Также похожий хадис рассказал нам Мухаммад ибн Башшар, которому рассказали ′Амр ибн ′Али и Яхья ибн Хаким от Яхьи ибн Са′ида, которому рассказал ′Убейдуллах."]],[["p","278 ― Также похожий хадис рассказали нам Бундар и Яхья ибн Хаким от Яхьи, а тот — от ′Убейдуллаха, которому рассказал Са′ид ибн Аби Са′ид аль-Макбури от Абу Хурейры (да будет доволен им Аллах)."],["p","279 ― Также похожий хадис рассказал нам Яхья ибн Хаким, которому рассказал ′Абд уль-Уаххаб ибн ′Абд уль-Маджид, а ему рассказали Хишам ибн Хассан и ′Убейдуллах от Са′ида, а тот — от Абу Хурейры (да будет доволен им Аллах)."],["p","280 ― Также похожий хадис рассказал нам Яхья ибн Хаким, которому рассказал Ибн Аби ′Ади от Мухаммада ибн Исхака, которому рассказал Са′ид ибн Аби Са′ид аль-Макбури от ′Ата (вольноотпущенник Умм Субеййи), а тот — от Абу Хурейры (да будет доволен им Аллах)."],["p","281 ― Также похожий хадис рассказал нам Абу Муса, которому рассказал Ибн Аби ′Ади от Хишама, а тот — от Яхьи ибн Аби Касира, который передавал от Абу Джа′фара, а тот слышал его от Абу Хурейры (да будет доволен им Аллах)."],["p","282 ― Также похожий хадис рассказал нам Мухаммад ибн ′Абд уль-А′ля, которому рассказал Халид ибн уль-Харис, а ему рассказал Хишам от Яхьи ибн Аби Касира, а тот — от Абу Джа′фара, который слышал его от Абу Хурейры (да будет доволен им Аллах)."],["p","283 ― Также похожий хадис рассказал нам Мухаммад ибн Яхья, которому рассказал Мухадыр, а ему рассказал аль-А′маш от Абу Салиха, который передавал от Абу Са′ида аль-Худри и Абу Хурерйы."],["p","284 ― Также похожий хадис дошёл до нас от Абу Исхака и Хабиба, которые передавал от аль-Агарра, а он — от Абу Хурейры."],["p","285 ― Также похожий хадис рассказал нам Абу Яхья Мухаммад ибн ′Абд ур-Рахим аль-Баззаз, которому рассказал Абу Бадр Шуджа′ ибн уль-Уалид, а ему рассказал Са′д ибн Са′ид, который слышал от Са′ида ибн Марджаны, а тот — от Абу Хурейры."],["p","286 ― Также похожий хадис рассказали нам Мухаммад ибн Яхья и Исхак ибн Уахб аль-Уаситы, которым рассказал Мухадыр, а ему рассказал Са′д ибн Са′ид ибн Кайс, которому рассказал Са′ид ибн Аби Са′ид ибн Марджана, который слышал от Абу Хурейры."],["p","287 ― Также похожий хадис рассказал нам Мухаммад ибн Рафи′, которому рассказал Мухаммад ибн Исма′иль ибн Аби Фудейк, а ему рассказал Ибн Аби Зиб от аль-Касима ибн ′Аббаса, а тот — от Нафи′а ибн Джубейра, который передавал от Абу Хурейры."],["p","288 ― В другой версии сказано: <b><i>«Поистине, Пречистый и Всевышний Аллах нисходит в этот час на ближнее небо и говорит: \"Есть ли взывающий, чтобы Я ответил ему?! Есть ли просящий, чтобы Я даровал ему просимое им?! Есть ли просящий прощения, чтобы Я простил его?!\"».</i></b>"],["p","289 ― В версии Мухаммада ибн Исхака вместо глагола «йанзилю» приходит глагол «яхбиту»<sup class=\"fn\">423</sup>."],["n",[[423,"И это один из самых сильных доводов, указывающих на то, что предшественники понимали смысл атрибутов Аллаха и принимали их в буквальном смысле. Здесь один из передатчиков сказал вместо слова «йанзилю» слово «яхбиту», и оба этих слова переводятся как «нисходит», и это указывает на то, что он понимал значение этого слова и понимал его смысл, а иначе он не стал бы менять его на его синоним."]]]],[["p","290 ― В версии со слов Джабира сказано: <b><i>«…каждую ночь…». </i></b>"],["p","291 ― В версии со слов Хишама ад-Дастауаи сказано: <b><i>«…и это происходит каждую ночь…». </i></b>"],["p","292 ― Также похожий хадис рассказал нам аз-За′фарани, которому рассказал ′Абдуллах ибн Бакр ас-Сахми, а ему рассказал Хишам."],["p","293 ― Также похожий хадис рассказал нам аз-За′фарани, которому рассказал Язид ибн Харун, а ему рассказал ад-Дастауаи."],["p","294 ― Также похожий хадис рассказал нам Мухаммад ибн ′Абдуллах ибн Маймун в Александрии, а ему рассказал аль-Уалид от аль-Ауза′и, а тот — от Яхьи, а тот — от Хиляля ибн Аби Маймуны, который передавал от ′Ата ибн Ясара, а он рассказывал от Рифа′и аль-Джухани."],["p","295 ― Рифа′а ибн ′Араба аль-Джухани рассказывал: <i>«Однажды мы вместе с посланником Аллаха (да благословит его Аллах и приветствует) покинули Мекку, и люди стали просить у него разрешения (вернуться к своим семьям), и он разрешал им. Затем пророк (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Почему для вас та сторона дерева, которая ближе к посланнику Аллаха, ненавистнее, чем другая его сторона?!\"</i></b><sup class=\"fn\">424</sup>, <i>и тогда все люди заплакали. Абу Бакр ас-Сыддик сказал: \"Тот, кто попросит у тебя разрешения (отправиться домой) после этих (слов), действительно, глупец!\". Затем пророк (да благословит его Аллах и приветствует) встал, многократно восхвалил Аллаха и сказал: </i><b><i>\"Клянусь Тем, в Чьей рука моя душа! Я свидетельствую пред Аллахом о том, что любой из вас, кто уверует в Аллаха и в Последний День, а затем будет следовать по прямому пути, непременно будет введен в Рай! Мой Всемогущий и Великий Господь пообещал мне, что введет в Рай семьдесят тысяч (членов) моей общины без расчета и наказания, и, поистине, я надеюсь, что он не введет их в Рай, пока вы и те из ваших супруг и потомков, которые были праведными, не займете места в райских жилищах!\".</i></b>"],["n",[[424,"То есть для некоторых любимей вернуться к своим семьям, чем остаться вместе с посланником Аллаха (да благословит его Аллах и приветствует)."]]],["p","<i>Затем он сказал: </i><b><i>«Когда проходит половина ночи (или: две трети ночи) Всеблагой и Всевышний Аллах нисходит на ближнее небо и говорит: \"Я не стану спрашивать о Своих рабах никого, кроме Себя! Кто просит Меня (о чем-либо), чтобы Я даровал ему?! Кто взывает ко Мне, чтобы Я ответил ему?! Кто просит у Меня прощения, чтобы Я простил ему?!», </i></b><i>и так продолжается, пока не появится заря»</i><sup class=\"fn\">425</sup>."],["n",[[425,"Этот хадис передал имам Ахмад, 4/16, и он является достоверным. Все его передатчики являются передатчиками достоверных сборников. Также его передали ат-Таялиси в «Муснаде», стр. 182, и аль-Баззар, как об этом сказано в книге «Кашф уль-астар», 4/206."]]]],[["p","296 ― Также похожий хадис рассказал нам Мухаммад ибн Башшар, которому рассказал Хишам ибн ′Абд уль-Малик, а ему рассказал Хаммад ибн Саляма, который передавал от ′Амра ибн Динара."],["p","297 ― Джубейр ибн Мут′им (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Всеблагой и Всевышний Аллах нисходит каждую ночь на ближнее небо и говорит: \"Есть ли просящий, чтобы Я даровал ему?! Есть ли просящий прощения, чтобы Я простил его?!\"»</i></b><sup class=\"fn\">426</sup>."],["n",[[426,"Ахмад, 4/81; ан-Насаи в «ас-Сунан аль-кубра», 10321; ад-Дарими в «Сунане», 1480; Абу Я′ля в «Муснаде», 7408, 7409; Ибн Аби ′Асым в «ас-Сунна», 507; ′Абдуллах ибн Ахмад в «ас-Сунна», 1290; аль-Аджурри в «аш-Шари′а», 760; ат-Табарани в «аль-Му′джам аль-кабир», 2/134 и др."]]],["p","298 ― Нафи′ ибн Джубейр передал, что один из сподвижников пророка (да благословит его Аллах и приветствует) сказал: <i>«Когда проходит половина ночи, Всеблагой и Всевышний Аллах нисходит на ближнее небо, открывает его врата и говорит: \"Кто просит Меня, чтобы Я даровал ему?! Кто взывает ко Мне, чтобы Я ответил ему?!\", и так, пока не появится заря». </i>"],["p","299 ― В другой версии со слов Абу Хурейры (да будет доволен им Аллах) сказано: <b><i>«…и так продолжается, пока солнце не поднимется». </i></b>"],["p","300 ― ′Абдуллах ибн Мас′уд (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«В последнюю треть ночи Аллах открывает врата небес, а затем нисходит на ближнее небо, простирает Свои руки и говорит: \"Есть ли раб, который просит Меня, чтобы Я даровал ему?!\", и так продолжается, пока солнце не начнёт ярко светить»</i></b><sup class=\"fn\">427</sup>."],["n",[[427,"Ахмад, 1/466; аль-Аджурри в «аш-Шари′а», 758, 759; Абу Са′ид ад-Дарими в «ар-Радд ′аляль джахмия», 130; аль-Лялякаи в «И′тикад ахли ссунна», 757, 765; Ибн Батта в «аль-Ибана», 165."]]],["p","301 ― ′Усман ибн Аби-ль ′Ас (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Каждую ночь Всеблагой и Всевышний Аллах нисходит на ближнее небо и говорит: \"Есть ли взывающий, чтобы Я ответил ему?! Есть ли просящий, чтобы Я даровал ему?! Есть ли просящий о прощении, чтобы Я простил ему?!\"»</i></b><sup class=\"fn\">428</sup>."],["n",[[428,"Ахмад, 4/22, 217, 218; Ибн Аби ′Асым в «ас-Сунна», 508; ат-Табарани в «аль-Му′джам аль-кабир», 9/54."]]],["p","302 ― Также похожий хадис рассказал нам Мухаммад ибн Яхья, которому рассказал Абу-ль Уалид, а ему рассказал Хаммад ибн Саляма от ′Али ибн Зейда."],["p","303 ― Абу ад-Дарда (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Всемогущий и Великий Аллах нисходит в течение ночи в три временных промежутка. В первый временной промежуток Он открывает Книгу, которую не видит никто, кроме Него, и стирает, что пожелает, и утверждает, что пожелает. Затем Он нисходит во второй временной промежуток в сады ′Адна, которые не видели очи, и которые даже не представляло человеческое сердце. В этих садах поселятся из потомков Адама лишь три (категории): пророки, правдивые мужи и мученики. Затем Аллах говорит: \"Туба тому, кто вошёл в вас!\". Затем Он нисходит в третий временной промежуток к ближнему небу вместе со Своим духом и Своими ангелами, и тогда эти небеса начинают дрожать, а (Аллах) говорит: \"Стойте по Моему величию!\". После этого Он взирает на Своих рабов и говорит: \"Есть ли просящий прощения?! Я прощу ему! Есть ли взывающий?! Я отвечу ему!\", и так до самой утренней молитвы. Именно поэтому (Аллах) говорит: </i>\"…и читай Коран на рассвете. Воистину, на рассвете Коран читают при свидетелях\"</b><sup class=\"fn\">429</sup>. <b><i>На этой молитве присутствует Аллах и ангелы ночи и дня»</i></b><sup class=\"fn\">430</sup>."],["n",[[429,"Сура «аль-Исра», аят 78."],[430,"Ибн Джарир в «Тафсире», 6/415; Абу Са′ид ад-Дарими в «ар-Радд ′аляль джахмия», 120; ат-Табарани в «аль-Му′джам аль-аусат», 8635; аль-Лялякаи в «И′тикад ахли ссунна», 756; Ибн Батта в «аль-Ибана», 169."]]]],[["p","304 ― Также похожий хадис рассказал нам ′Али ибн Дауд аль-Кантари, которому рассказал ′Абдуллах ибн Салих, а ему рассказал аль-Лейс ибн Са′д."],["p","305 ― Аль-Касим ибн Мухаммад передал от своего отца или дяди, а тот — от его деда, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Всемогущий и Великий Аллах нисходит на ближнее небо в срединную ночь (месяца) ша′бан и прощает всем, кроме человека, в сердце которого есть злоба, и кроме того, кто придаёт Аллаху сотоварищей»</i></b><sup class=\"fn\">431</sup>."],["n",[[431,"Ибн Аби ′Асым в «ас-Сунна», 501; Абу Са′ид ад-Дарими в «ар-Радд ′аляль джахмия», 136; аль-Лялякаи в «И′тикад ахли ссунна», 750."]]],["h2","ГЛАВА 32: УПОМИНАНИЕ ТОГО, ЧТО АЛЛАХ ГОВОРИЛ С МУСОЙ. АЛЛАХ ВЫДЕЛИЛ ЕГО ЭТИМ СРЕДИ ОСТАЛЬНЫХ ПОСЛАННИКОВ"],["p","Мы начнём с упоминания общих аятов, которые не разъяснены подробно, а затем с помощью Аллаха и с Его содействием мы приведём и разъяснённые аяты Корана."],["p","Всевышний Аллах сказал: <b>«Таковы посланники. Одним из них Мы отдали предпочтение перед другими. Среди них были такие, с которыми говорил Аллах»</b><sup class=\"fn\">432</sup>."],["n",[[432,"Сура «аль-Бакара», аят 253."]]],["p","В этом аяте Всевышний Аллах не упомянул, с кем именно из посланников Он говорил. Он не упомянул ни имя этого посланника, ни его происхождение, ни его качества. Но тот, кто читает или слышит этот аят, узнает из других аятов, с каким именно посланником говорил Аллах. Также в этом аяте Аллах не упомянул, как именно Он говорил с посланниками, но Он разъяснил это в другом аяте: <b>«И не было так, чтобы Аллах говорил с человеком иначе, как посредством откровения или через завесу. Или же Он отправляет посланца, который с Его позволения внушает посредством откровения то, что Он желает»</b><sup class=\"fn\">433</sup>."],["n",[[433,"Сура «аш-Шура», аят 51."]]],["p","Аллах разъяснил здесь, как именно Он говорил с некоторыми людьми."],["p","Знай, что с некоторыми из них Аллах говорил посредством откровения или через завесу, или же Он отправляет посланца, который с Его позволения внушает посредством откровения то, что Он желает."],["p","Также Аллах сказал: <b>«И Аллах говорил с Мусой (истинным) разговором»</b><sup class=\"fn\">434</sup><b>. </b>"],["n",[[434,"Сура «ан-Ниса», аят 164."]]],["p","Здесь Аллах разъяснил, что Он говорил с Мусой (мир ему и благословение Аллаха) истинным разговором. Таким образом, в этом аяте Аллах разъяснил Своим верующим рабам то, что пришло без разъяснения в словах Аллаха: <b>«Среди них были такие, с которыми говорил Аллах». </b>В этом аяте Аллах назвал, с кем именно Он говорил. Аллах сообщил, что это — Муса, которого Аллах выделил Своей речью."],["p","Также Всевышний Аллах сказал: <b>«И когда пришел Муса к назначенному Нами сроку, и беседовал с ним Господь…»</b><sup class=\"fn\">435</sup>."],["n",[[435,"Сура «аль-А′раф», аят 143."]]]],[["p","Этот аят также разъясняет тот первый аят. В этом аяте Аллах назвал того, с кем Он говорил. Аллах сообщил, что это — Муса, которого Он выделил среди всех посланников (да благословит его Аллах). Аллах сообщил, что это именно его Господь говорил с ним."],["p","В другом аяте Всевышний Аллах сообщил, что избрал Мусу Своим посланием и Своей речью. Всемогущий и Великий Аллах сказал: <b>«О, Муса! Поистине, Я избрал тебя пред людьми Моими посланиями и Моей речью. Бери же то, что Я дам тебе, и будь из (числа) благодарных!»</b><sup class=\"fn\">436</sup><b>.</b>"],["n",[[436,"Сура «аль-А′раф», аят 144."]]],["p","В другом аяте Аллах разъяснил, что именно Он сказал Мусе. Аллах сказал в суре «Та Ха»: <b>«А когда он подошел к нему </b>[к огню]<b>, раздался голос: \"О, Муса! Поистине, Я — твой Господь. Сними же свои сандалии! Ведь ты находишься в священной долине Тува. И Я избрал тебя; прислушайся же к тому, что тебе сообщается через откровение. Воистину, Я — Аллах! (И) нет (другого) истинного бога, кроме Меня! Поклоняйся же Мне и совершай молитву в Мое воспоминание </b>[чтобы помнить обо Мне]<b>!\"»</b><sup class=\"fn\">437</sup>."],["n",[[437,"Сура «Та Ха», аяты 11-14."]]],["p","А в суре «ан-Намль» Аллах сказал: <b>«Вот сказал Муса своей семье: \"Поистине, я заметил (вдали) огонь; вскоре я принесу вам оттуда известие…\", </b>и до слов Аллаха: <b>«О, Муса, поистине, Я — Аллах, Величественный, Мудрый»</b><sup class=\"fn\">438</sup>."],["n",[[438,"Сура «ан-Намль», аяты 7-9."]]],["p","Также Аллах сказал в суре «аль-Касас»: <b>«И когда он </b>[Муса]<b> подошел к нему </b>[к огню]<b>, был к нему обращен зов (Аллаха) с правой (от него) стороны долины в благословенной роще со стороны дерева: \"О, Муса! Поистине, Я — Аллах, Господь миров!\"»</b><sup class=\"fn\">439</sup>."],["n",[[439,"Сура «аль-Касас», аят 30."]]],["p","В этих трёх аятах Аллах разъяснил некоторые слова, с которыми Он обратился к Мусе, и эти слова не мог произнести ни приближенный ангел, ни какой-то иной ангел. Ангел не мог обратиться к Мусе со словами: <b>«Поистине, Я — Аллах, Господь миров!». </b>Ангел не мог сказать: <b>«Поистине, Я — твой Господь. Сними же свои сандалии!»</b><sup class=\"fn\">440</sup>."],["n",[[440,"Дело в том, что некоторые заблудшие говорят, что, на самом деле, имеется в виду, что с Мусой говорил ангел, а не Аллах, так как Аллах по их убеждениям не говорит. Но приверженцы сунны отвечают им, что ангел никак не мог обратиться к Мусе с такими словами и ангел никак не мог сказать: «Я — Аллах»."]]],["p","Также Всевышний Аллах сказал: <b>«И исполнилось благое слово твоего Господа над потомками Исраиля за то, что они терпели!»</b><sup class=\"fn\">441</sup><b>.</b>"],["n",[[441,"Сура «аль-А′раф», аят 137."]]],["p","В этом аяте Аллах сообщил, что у Него есть слова, которые Он произносит."],["p","<b>Сейчас же послушайте ясные слова пророка (да благословит его Аллах и приветствует), которые были переданы надежными передатчиками по непрерывным цепочкам. Эти слова разъясняют, что Аллах избрал Мусу Своей речью среди всех остальных посланников (мир им). </b>"]],[["p","306 ― Абу Хурейра (да будет доволен им Аллах) передал, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Однажды Муса встретит Адама…», </i></b>и далее в этом хадисе сказано: <b><i>«Адам сказал: \"Разве ты не Муса, которого Аллах избрал среди людей Своим посланиям и Своей речью?!\"»</i></b><sup class=\"fn\">442</sup>."],["n",[[442,"Похожие хадисы в полном виде уже были приведены в главах 11 и 12. Этот хадис передали ан-Насаи в «ас-Сунан аль-кубра», 11186; аль-Лялякаи в «И′тикад ахли ссунна», 1035; Ибн Аби ′Асым в «ас-Сунна», 139; Ибн Манда в «ар-Радд ′аляль джахмия», 26 и др."]]],["p","307 ― В другой версии со слов Абу Хурейры (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Адам сказал: \"Аллах избрал тебя Своей речью и начертил для тебя Тору Своей рукой\"»</i></b><sup class=\"fn\">443</sup>."],["n",[[443,"Аль-Бухари, 6614; Муслим, 2652; Абу Дауд, 4701; Ибн Маджа, 80; Ахмад, 2/248; Ибн Хиббан, 6180 и др."]]],["p","308 ― В третьей версии со слов Абу Хурейры (да будет доволен им Аллах) пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Адам сказал: \"Ты — Муса! Аллах избрал тебя Своей речью и Своим посланием, и говорил с тобой (истинным) разговором\"»</i></b><sup class=\"fn\">444</sup>."],["n",[[444,"Эта версия уже была приведена в книге под № 94."]]],["p","309 ― В четвертой версии пришло, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Адам сказал: \"Ты — Муса, которого Аллах избрал Своей речью и Своим посланием\"»</i></b><sup class=\"fn\">445</sup>."],["n",[[445,"Эта версия уже была приведена в книге под № 95."]]],["p","310 ― Шари́к ибн ′Абдуллах ибн Аби Намир слышал, как Анас ибн Малик (да будет доволен им Аллах) рассказывал длинный хадис о том, как пророк (да благословит его Аллах и приветствует) был перенесён ночью (аль-исра) из мечети, в которой Кааба."],["p","Шари́к ибн ′Абдуллах рассказывал: <i>«На каждом небе были пророки. Анас назвал их по именам, а я запомнил только то, что на втором небе был Идрис, на четвертом — Харун, на пятом — кто-то другой, но я не запомнил его имени, на шестом — Ибрахим, а на седьмом — Муса, ибо он говорил с Аллахом. Муса сказал: \"Господи! Я не думал, что кого-то поднимут выше меня!\". Но (пророка Мухаммада) подняли выше настолько, насколько знает только Аллах, пока он не дошёл до лотоса крайнего предела (сидрат аль-мунтаха)</i><sup class=\"fn\">446</sup><i>. И тогда Могущественный Господь величия приблизился и снизошёл так, что оказался от него на расстоянии двух полетов стрелы и даже еще ближе, и внушил Он откровением Своему рабу то, что пожелал, и среди того, что Он внушил ему, было вменение в обязанность для его общины пятидесяти молитв в течение дня и ночи</i><sup class=\"fn\">447</sup><i>. Затем (пророк) спустился и дошёл до Мусы…», </i>и так далее до конца хадиса<sup class=\"fn\">448</sup>."],["n",[[446,"Сказал Мухаммад аль-Мубаракфури, разъясняя один из хадисов на эту тему: <i>«Ан-Науауи сказал, что этот лотос назван лотосом крайнего предела, так как знание ангелов заканчивается на нем, и никто, кроме посланника Аллаха (да благословит его Аллах и приветствует), не ступал дальше него».</i> См. «Тухфат уль-ахуази», хадис № 2541."],[447,"Затем количество этих молитв было сокращено до пяти."],[448,"Аль-Бухари, 7517; Муслим, 162; Ибн Манда в «аль-Иман», 712; аль-Лялякаи в «И′тикад ахли ссунна», 1423."]]]],[["p","311 ― Абу Хурейра и Хузейфа (да будет доволен ими Аллах) передали, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Аллах соберёт людей и верующие будут стоять, пока не будет приближен Рай. Они придут к Адаму и скажут: \"О наш отец! Попроси открыть Рай для нас!\", но он ответит: \"А разве вас вывело из Рая что-то, кроме проступка вашего праотца?! Я не для этого. Ступайте к моему сыну Ибрахиму, любимцу Господа\". Но Ибрахим скажет: \"Я не для этого. Я был любимцем (Аллаха, но говорил с ним) только через завесу. Ступайте к моему сыну Мусе, с которым Аллах говорил (истинным) разговором\". Тогда они отправятся к Мусе», </i></b>и они упомянули этот хадис целиком<sup class=\"fn\">449</sup>."],["n",[[449,"Муслим, 195; Абу Я′ля, 6216; Ибн Манда в «аль-Иман», 883; аль-Хаким в «аль-Мустадрак», 8749."]]],["p","312 ― ′Умейр ибн Исхак рассказывал, что однажды Джа′фар ибн Аби Талиб сказал: <i>«О пророк Аллаха! Позволь мне отправиться в землю, где я смогу поклоняться Аллаху и не бояться никого». </i>Пророк (да благословит его Аллах и приветствует) позволил ему, и он прибыл в Эфиопию."],["p","′Амр ибн уль-′Ас рассказывал: <i>«Когда я увидел, что Джа′фар и его товарищи живут в Эфиопии в безопасности, я стал завидовать ему и сказал: \"Я непременно встречусь с ним и с его товарищами!\". Затем я прибыл к негусу (правителю Эфиопии) и сказал: \"В твоей земле живёт человек, а сын его дяди в наших землях утверждает, что у людей только один Бог. Клянусь Аллахом, если ты не убьёшь его и его товарищей, то ни я, ни кто-либо из моих товарищей более никогда не приедет к тебе (по торговым делам). (Негус) сказал: \"Ступай к нему и пригласи его\", но я ответил: \"Он не согласится прийти со мной\", и тогда он отправил со мной посланца. Я пришёл к Джа′фару, когда он находился среди своих товарищей и говорил с ними. Мы пригласили его (к негусу), и когда мы подошли к (его) двери, я сказал громким голосом: \"Позволь войти ′Амру ибн уль-′Асу\", а (Джа′фар) громко сказал: \"Позволь войти партии Аллаха!\". (Негус) услышал его голос и позволил ему войти раньше меня. Джа′фар сел перед троном, а его товарищи вокруг него на подушках. А когда я вошёл, я сел между ним и троном. Так он оказался позади меня. Я также посадил между каждыми двумя из них одного из своих спутников. Негус сказал: \"Говори, о ′Амр ибн уль-′Ас!\". Я сказал: \"Сын дяди этого человека в наших землях утверждает, что нет у людей истинного бога, кроме Одного. Клянусь Аллахом, если ты не убьёшь его и его товарищей, то ни я, ни кто-либо из моих товарищей более никогда не приедет к тебе (по торговым делам)\". Тогда негус сказал: \"Говорите, о партия Аллаха, говорите!\". </i>"]],[["p","<i>(Джа′фар) многократно восхвалил Аллаха, засвидетельствовал, что нет истинного бога, кроме Аллаха, и что Мухаммад — посланник Аллаха, и сказал: \"Он (′Амр) сказал правду! Он (пророк) — сын моего дяди, и я на его религии\". Клянусь Аллахом! В тот день я в первый раз услышал свидетельство (ислама). Затем (негус) поднял руку и спросил: \"О Джа′фар! А что он говорит об ′Исе (Иисусе)?!\". (Джа′фар) сказал: \"Он говорит, что ′Иса — дух от Аллаха и Его слово\", и тогда (негус) поднял что-то мелкое с земли и сказал: \"Он не ошибся относительно него даже на размер этого! Вставайте, о партия Аллаха! Ты будешь в безопасности на моей земле. Если кто-то убьет тебя, я убью его, а если кто-то обругает тебя, я возложу на него штраф. Если бы ни моя власть и мой народ, я бы непременно проследовал за тобой (к нему). Вставай же!\". Затем он сказал своему стражнику: \"Запомни его, и никогда не мешай ему входить ко мне, если только я не буду со своей семьей, но даже в том случае, если ему обязательно нужно будет войти ко мне, то позволь ему. А ты, о ′Амр ибн уль-′Ас, вставай и, клянусь Аллахом, мне не важно, даже если ты больше никогда не приедешь ко мне (по торговым делам), и не приедет никто из твоих товарищей\". </i>"],["p","<i>И когда мы вышли от негуса, я никого не хотел встретить так сильно, как хотел встретить Джа′фара. В один из дней я повстречал его на улице, посмотрел на него и не увидел никого с ним, а он не увидел никого со мной. Я взял его за руку и сказал: \"Знай, что я свидетельствую, что нет истинного бога, кроме Аллаха, и что Мухаммад — посланник Аллаха\". Он сжал мою руку и сказал: \"Аллах наставил тебя! Будь же стоек!\". А когда я пришёл к своим спутникам, то, клянусь Аллахом, они словно видели меня вместе с Джа′фаром. Они схватили меня, накинули на моё лицо кусок ткани и держали меня так, а я стал бороться с ними и вырвался из их рук, но оказался без одежды. Я подошел к эфиопке и снял покрывало с её головы, а она сказал мне то-то и то-то. </i>"],["p","<i>Затем я пришел к Джа′фару, который сидел перед своими товарищами и рассказывал им что-то. Я сказал: \"Когда я покинул тебя, они сделали со мной то-то и то-то и забрали у меня всё, что было. А то, что ты видишь на мне сейчас, я снял с головы эфиопки\". Тогда он ушел, отправился к дверам (негуса) и сказал: \"Позволь войти партии Аллаха!\". Вышел стражник и сказал: \"Негус сейчас со своей семьей!\". Джа′фар сказал: \"Все равно разреши мне войти!\", и тот разрешил ему войти, и он вошёл. Джа′фар сказал (негусу): \"′Амр ибн уль-′Ас оставил свою религию и последовал за моей религией!\". Тот сказал: \"Не может быть!\". Я сказал: \"Всё именно так!\". Тот (вновь) сказал: \"Не может быть!\". Я сказал: \"Всё именно так!\". Тот (вновь) сказал: \"Не может быть!\". Я сказал: \"Всё именно так!\". Тогда негус сказал стражнику: \"Ступай и если всё так, как он говорит, то купи ему всё, о чем он попросит!\". И я написал ему всё, что мне нужно, даже платки и кружки. И если бы я захотел взять у них имущество, я бы мог сделать это»</i><sup class=\"fn\">450</sup>."],["n",[[450,"В цепочке передатчиков этого сообщения есть определенная слабость. А Аллах знает лучше!"]]]],[["p","ГЛАВА 33: РАЗЪЯСНЕНИЕ ТОГО, ЧТО ВЕЛИКИЙ И ВОЗВЫШЕННЫЙ АЛЛАХ ГОВОРИЛ С МУСОЙ (МИР ЕМУ) ЧЕРЕЗ ЗАВЕСУ, НО МЕЖДУ ВСЕБЛАГИМ И ВСЕВЫШНИМ АЛЛАХОМ И МУСОЙ (МИР ЕМУ) НЕ БЫЛО ПОСРЕДНИКА, КОТОРЫЙ ДОНОСИЛ БЫ ДО НЕГО СЛОВА ЕГО ГОСПОДА. ОДНАКО КОГДА МУСА (МИР ЕМУ) ГОВОРИЛ СО СВОИМ ВСЕМОГУЩИМ И ВЕЛИКИМ ГОСПОДОМ, ОН НЕ ВИДЕЛ ЕГО"],["p","313 ― ′Умар ибн уль-Хаттаб (да будет доволен им Аллах) передал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Муса скажет: \"Господи, покажи нам Адама, который вывел и нас, и себя из Рая\". И Аллах покажет ему Адама. Муса спросит: \"Ты наш праотец Адам?\". Адам ответит ему: \"Да\". Муса спросит: \"Ты тот, в кого Аллах вдохнул от Своего духа, и кого научил всем именам, и перед кем повелел пасть ниц ангелам?\". Он ответил: \"Да\". Муса спросит: \"А что побудило тебя (сделать то, из-за чего ты) вывел и нас, и себя из Рая?\". Адам скажет ему: \"А ты кто?\". Муса ответит: \"Я Муса\". Адам спросит: \"Ты пророк потомков Исраиля, с которым говорил Аллах через завесу, и не сделал между тобой и Им посланца из числа Его творений?\". Он ответит: \"Да\". Адам спросит: \"Разве ты не обнаружил всё это записанным в Книге Аллаха до моего сотворения?\". Он ответит: \"Да, (обнаружил)\". (Адам) скажет: \"Почему же ты упрекаешь меня за то, что Всевышний Аллах предопределил мне до моего сотворения?\"».</i></b>"],["p","Здесь посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Так Адам победил Мусу в споре»</i></b><sup class=\"fn\">451</sup>."],["n",[[451,"Абу Дауд, 4702; Ибн Аби ′Асым в «ас-Сунна», 137; аль-Аджурри в аш-Шари′а, 201; Абу Са′ид ад-Дарими в «ар-Радд ′аляль джахмия», 294; Ибн Манда в «ар-Радд ′аляль джахмия», 38; Абу Я′ля, 243; Ибн Батта в «аль-Ибана», 1378."]]],["p","ГЛАВА 34: ОПИСАНИЕ ТОГО, КАК АЛЛАХ ПРОИЗНОСИТ ОТКРОВЕНИЕ, И СИЛЬНЫЙ СТРАХ НЕБЕС ПЕРЕД НИМ. УПОМИНАНИЕ ТОГО, КАК ОБИТАТЕЛИ НЕБЕС ПАДАЮТ БЕЗ СОЗНАНИЯ И СОВЕРШАЮТ ЗЕМНЫЕ ПОКЛОНЫ ПЕРЕД ВСЕМОГУЩИМ И ВЕЛИКИМ АЛЛАХОМ"],["p","314 ― Ан-Наууас ибн Сам′ан (да будет доволен им Аллах) рассказывал, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Когда Всемогущий и Великий Аллах желает внушить какое-либо повеление, Он произносит откровение, а когда Он говорит, небеса начинают сильно трястись (или: греметь) из страха пред Аллахом. Когда это слышат обитатели небес, они падают ниц пред Аллахом и теряют сознание, а первым свою голову поднимает Джибриль. Аллах произносит ему из Своего откровения то, что пожелает, а затем Джибриль проходит мимо ангелов и каждый раз, как он проходит через какое-либо небо, обитатели этого неба спрашивают: \"Что сказал наш Господь, о Джибриль?!\". Джибриль отвечает: \"Он сказал истину, ибо Он — Возвышенный, Великий!\", и тогда все они повторяют эти слова за Джибрилем, после чего Джибриль отправляется с откровением туда, куда ему повелел Аллах»</i></b><sup class=\"fn\">452</sup>."],["n",[[452,"Передал ат-Табари в своём толковании Корана, 20/397, и ат-Табарани, как об этом сказано в «Маджма′ аз-Зауаид», 7/97."]]]]];
